changeSet.sql:
CREATE TABLE vaultnote.rate_limit_counters (
    rate_limit_key_hash CHAR(64) NOT NULL,
    request_count INTEGER NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_rate_limit_counters PRIMARY KEY (rate_limit_key_hash),
    CONSTRAINT ck_rate_limit_counters_request_count CHECK (request_count >= 0)
);

CREATE INDEX ix_rate_limit_counters_expires_at
    ON vaultnote.rate_limit_counters (expires_at);
